import type { Bi } from "./lessons";

/**
 * Per-lab assessments.
 *
 * These are deliberately NOT command exercises. The task hints in a lab tell
 * the student what to type; an assessment question asks what they would decide
 * when the terminal is not in front of them — audit findings, conflicting
 * evidence, pressure to cut a corner, and the boundary of what they are allowed
 * to touch. `scripts/test-progress-rules.mjs` enforces that no assessment text
 * reproduces a command from the lab it belongs to.
 */
export type AssessmentQ = {
  scenario: Bi;
  q: Bi;
  choices: Bi[];
  answer: number;
  why: Bi;
};

